package httpcaddyfile

import (
	"encoding/json"
	"testing"

	"github.com/caddyserver/caddy/v2/caddyfile"
)

func TestClientIPMultipleLinesInNotBlock(t *testing.T) {
	input := []byte(`{
    servers {
        trusted_proxies static 173.245.48.0/20
    }
}

@webhook {
    path "/webhook"
    not {
        client_ip 51.138.37.238 20.54.89.16 40.127.253.112/28
        client_ip 20.50.240.57 94.70.170.65
        client_ip 1.2.3.4
    }
}
handle @webhook {
    abort
}`)

	adapter := caddyfile.Adapter{
		ServerType: ServerType{},
	}
	cfg, warnings, err := adapter.Adapt(input, nil)
	if err != nil {
		t.Fatalf("adapt: %v", err)
	}
	if len(warnings) > 0 {
		t.Logf("warnings: %v", warnings)
	}

	var doc struct {
		Apps struct {
			HTTP struct {
				Servers map[string]struct {
					Routes []struct {
						MatchersSetsRaw []map[string]json.RawMessage `json:"match"`
						Handlers        []map[string]json.RawMessage `json:"handle"`
					} `json:"routes"`
				} `json:"servers"`
			} `json:"http"`
		} `json:"apps"`
	}
	if err := json.Unmarshal(cfg, &doc); err != nil {
		t.Fatal(err)
	}
	srv := doc.Apps.HTTP.Servers["srv0"]
	if len(srv.Routes) != 1 {
		t.Fatalf("expected 1 route, got %d", len(srv.Routes))
	}
	ms := srv.Routes[0].MatchersSetsRaw
	if len(ms) != 1 {
		t.Fatalf("expected 1 matcher set, got %d", len(ms))
	}
	raw, ok := ms[0]["not"]
	if !ok {
		t.Fatalf("expected 'not' matcher in set: %v", ms[0])
	}
	var notMatcher struct {
		MatcherSetsRaw []map[string]json.RawMessage `json:"matcher_sets_raw"`
	}
	if err := json.Unmarshal(raw, &notMatcher); err != nil {
		t.Fatal(err)
	}
	if len(notMatcher.MatcherSetsRaw) != 1 {
		t.Fatalf("expected 1 matcher set in not, got %d", len(notMatcher.MatcherSetsRaw))
	}
	rawClientIP, ok := notMatcher.MatcherSetsRaw[0]["client_ip"]
	if !ok {
		t.Fatalf("expected 'client_ip' matcher inside not: %v", notMatcher.MatcherSetsRaw[0])
	}
	var clientIP struct {
		Ranges []string `json:"ranges"`
	}
	if err := json.Unmarshal(rawClientIP, &clientIP); err != nil {
		t.Fatal(err)
	}
	expected := []string{"51.138.37.238", "20.54.89.16", "40.127.253.112/28", "20.50.240.57", "94.70.170.65", "1.2.3.4"}
	if len(clientIP.Ranges) != len(expected) {
		t.Fatalf("expected %d ranges, got %v", len(expected), clientIP.Ranges)
	}
	for i, exp := range expected {
		if clientIP.Ranges[i] != exp {
			t.Fatalf("range %d: expected %s, got %s", i, exp, clientIP.Ranges[i])
		}
	}
}

