package httpcaddyfile

import (
	"encoding/json"
	"regexp"
	"testing"

	"github.com/caddyserver/caddy/v2/caddyfile"
)

func TestClientIPMultipleLinesInNotBlock(t *testing.T) {
	input := []byte(`{
	servers {
		trusted_proxies static 173.245.48.0/20
	}
}

example.com {
	@webhook {
		path "/webhook"
		not {
			client_ip 51.138.37.238 20.54.89.16 40.127.253.112/28
			client_ip 20.50.240.57 94.70.170.65
			client_ip 1.2.3.4
		}
	}
	handle @webhook {
		abort
	}
}`)

	adapter := caddyfile.Adapter{
		ServerType: ServerType{},
	}
	cfg, warnings, err := adapter.Adapt(input, nil)
	if err != nil {
		t.Fatalf("adapt: %v", err)
	}
	for _, w := range warnings {
		if w.Reminder != "Caddyfile input is not formatted" {
			t.Errorf("warning: %v", w)
		}
	}

	re := regexp.MustCompile(`"client_ip":\{"ranges":\[([^\]]*)\]}`)
	matches := re.FindAllStringSubmatch(string(cfg), -1)
	if len(matches) != 1 {
		t.Fatalf("expected 1 client_ip matcher, got %d in: %s", len(matches), cfg)
	}

	var ranges []string
	if err := json.Unmarshal([]byte("["+matches[0][1]+"]"), &ranges); err != nil {
		t.Fatal(err)
	}

	expected := []string{"51.138.37.238", "20.54.89.16", "40.127.253.112/28", "20.50.240.57", "94.70.170.65", "1.2.3.4"}
	if len(ranges) != len(expected) {
		t.Fatalf("expected %d ranges, got %v", len(expected), ranges)
	}
	for i, exp := range expected {
		if ranges[i] != exp {
			t.Fatalf("range %d: expected %s, got %s", i, exp, ranges[i])
		}
	}
}

